      --danger: #f04444;
      --danger-strong: #ff6b6b;
      --border: #343b4f;
      --shadow: 0 24px 80px rgb(0 0 0 / 0.55);
    }

    * {
      box-sizing: border-box;
    }

    html {
      min-height: 100%;
    }

    body {
      min-height: 100vh;
      margin: 0;
      background:
        radial-gradient(circle at top left, rgb(139 92 246 / 0.24), transparent 32rem),
        radial-gradient(circle at bottom right, rgb(240 68 68 / 0.16), transparent 28rem),
        var(--bg);
      color: var(--text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      line-height: 1.5;
    }

