      border-radius: 1rem;
      aspect-ratio: 16 / 10;
      object-fit: cover;
      background: #202536;
      box-shadow: 0 18px 42px rgb(0 0 0 / 0.35);
    }

    figcaption {
      margin-top: 1rem;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .card-body {
      display: flex;
