      align-items: center;
      justify-content: space-between;
      padding: 0 clamp(1rem, 4vw, 2rem) clamp(1rem, 4vw, 2rem);
    }

    h1 {
      margin: 0;
      font-size: clamp(1.8rem, 6vw, 3.5rem);
