    .dialog-title {
      margin: 0;
      font-size: clamp(1.45rem, 8vw, 2rem);
      line-height: 1.1;
    }

    .dialog-copy {
      margin: 0.9rem 0 0;
      color: var(--muted);
    }

    .dialog-actions {
      display: flex;
      flex-wrap: wrap-reverse;
      gap: 0.75rem;
      justify-content: flex-end;
      margin-top: 1.5rem;
    }

    .dialog-actions button {
      flex: 1 1 9rem;
    }

    .status-message {
      margin: 1rem 0 0;
      color: var(--danger-strong);
      font-weight: 700;
    }

    @media (max-width: 40rem) {
      main {
        padding: 1rem;
      }

      .card-body,
      .dialog-actions {
        align-items: stretch;
        flex-direction: column;
      }

      .trigger,
      .dialog-actions button {
        width: 100%;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
