      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <main id="main-content">
    <article class="preview-card" aria-labelledby="page-title">
      <figure class="image-frame">
        <img
          src="https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&amp;fit=crop&amp;w=1200&amp;q=80"
          alt="A quiet lakeside cabin surrounded by trees at golden hour"
        >
        <figcaption>Lakehouse at dusk - added to your travel inspiration library.</figcaption>
      </figure>

      <div class="card-body">
        <div>
          <h1 id="page-title">Lakehouse at dusk</h1>
          <p class="metadata">Image preview - Travel inspiration</p>
          <p id="delete-status" class="status-message" aria-live="polite"></p>
        </div>
        <button type="button" class="trigger" aria-haspopup="dialog">Delete image</button>
      </div>
    </article>
  </main>

  <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
    <div class="dialog-content">
      <p class="dialog-eyebrow">Confirm deletion</p>
      <h2 id="dialog-title" class="dialog-title">Delete this image?</h2>
      <p id="dialog-description" class="dialog-copy">
        This will remove "Lakehouse at dusk" from your library. This action cannot be undone.
      </p>
      <form method="dialog" class="dialog-actions">
        <button type="button" class="cancel" value="cancel">Cancel</button>
        <button type="submit" class="confirm-delete" value="delete">Delete image</button>
      </form>
    </div>
  </dialog>

  <script>
    const deleteDialog = document.querySelector("#delete-dialog");
    const openDialogButton = document.querySelector(".trigger");
    const cancelButton = document.querySelector(".cancel");
    const deleteStatus = document.querySelector("#delete-status");

    openDialogButton.addEventListener("click", () => {
      deleteDialog.showModal();
    });

    cancelButton.addEventListener("click", () => {
      deleteDialog.close("cancel");
    });

    deleteDialog.addEventListener("close", () => {
      if (deleteDialog.returnValue === "delete") {
        deleteStatus.textContent = "Image deleted from your library.";
        openDialogButton.disabled = true;
        openDialogButton.textContent = "Image deleted";
      }
    });
  </script>
</body>
</html>
